en = false\r\n        for _, handler in ipairs(self._closeHandlers) do pcall(handler) end\r\n    end\r\n    function socket:OnMessage(handler)\r\n        if type(handler) == \"function\" then table.insert(self._messageHandlers, handler) end\r\n    end\r\n    function socket:OnClose(handler)\r\n        if type(handler) == \"function\" then table.insert(self._closeHandlers, handler) end\r\n    end\r\n    return socket\r\nend\r\n\r\nlocal coreGuiTypes = { Enum.CoreGuiType.All, Enum.CoreGuiType.Backpack, Enum.CoreGuiType.Chat, Enum.CoreGuiType.Health, Enum.CoreGuiType.PlayerList }\r\nfor _, guiType in ipairs(coreGuiTypes) do\r\n    pcall(function() G.StarterGui:SetCoreGuiEnabled(guiType, true) end)\r\nend\r\n\r\nlocal screenGui = Instance.new(\"ScreenGui\")\r\nscreenGui.Name = \"UncSupport\"\r\nscreenGui.ResetOnSpawn = false\r\nscreenGui.IgnoreGuiInset = true\r\npcall(function() screenGui.Parent = G.CoreGui end)\r\n\r\nG.isfunction = function(obj) return type(obj) == \"function\" end\r\nG.istable = function(obj) return type(obj) == \"table\" end\r\nG.isuserdata = function(obj) return type(obj) == \"userdata\" end\r\nG.getinfo = function(level) return G.debug.getinfo(level or 2) end\r\n\r\nG.print(\"injected :D\")"),
