tgenv().syn.WebSocket.connect = function(url)\r\n        return nativeWebSocket.connect(url)\r\n    end\r\nelse\r\n    getgenv().syn.WebSocket.connect = function(url)\r\n        if (type(url) ~= \"string\") then\r\n            return nil, \"URL must be a string.\"\r\n        end\r\n        if not (url:match(\"^ws://\") or url:match(\"^wss://\")) then\r\n            return nil, \"Invalid WebSocket URL. Must start with 'ws://' or 'wss://'.\"\r\n        end\r\n        \r\n        local httpUrl = url:gsub(\"^ws://\", \"http://\"):gsub(\"^wss://\", \"https://\")\r\n        \r\n        local ws = { _url = url, _httpUrl = httpUrl, _connected = false, OnMessage = {}, OnClose = {} }\r\n        \r\n        ws.Connect = function(self)\r\n            local response = syn.request({\r\n                Url = self._httpUrl .. \"/connect\",\r\n                Method = \"GET\",\r\n                Timeout = 10\r\n            })\r\n            if response and response.StatusCode == 200 then\r\n                self._connected = true\r\n                return true\r\n            end\r\n            return false, \"Failed to connect\"\r\n        end\r\n        \r\n        ws.Send = function(self, message)\r\n            if not self._connected then return false, \"Not connected\" end\r\n            local response = syn.request({ Url = self._httpUrl .. \"/send\", Method = \"POST\", Headers = { [\"Content-Type\"] = \"text/plain\" }, Body = tostring(message), Timeout = 10 })\r\n            if response and response.StatusCode == 200 then\r\n                return true\r\n            end\r\n            return false, \"Failed to send\"\r\n        end\r\n        \r\n        ws.Close = function(self)\r\n            if not self._connected then return false, \"Not connected\" end\r\n            local response = syn.request({ Url = self._httpUrl .. \"/close\", Method = \"GET\", Timeout = 10 })\r\n            self._connected = false\r\n            if self.OnClose then for _, callback in ipairs(self.OnClose) do pcall(callback, \"closed\") end end\r\n            return true\r\n        end\r\n        \r\n        ws.Receive = function(self)\r\n            if not self._connected then return nil, \"Not connected\" end\r\n            local response = syn.request({ Url = self._httpUrl .. \"/receive\", Method = \"GET\", Timeout = 30 })\r\n            if response and response.StatusCode == 200 then\r\n                local message = response.Body or \"\"\r\n                if message ~= \"\" then\r\n                    if self.OnMessage then for _, callback in ipairs(self.OnMessage) do pcall(callback, message) end end\r\n                    return message\r\n                end\r\n            end\r\n            return nil\r\n        end\r\n        \r\n        task.spawn(function()\r\n            while ws._connected do\r\n                task.wait(0.5)\r\n                pcall(function() ws:Receive() end)\r\n            end\r\n        end)\r\n        \r\n        local connected, err = ws:Connect()\r\n        if not connected then return nil, err or \"Failed to connect\" end\r\n        return ws\r\n    end\r\nend\r\n\r\nlocal metatableRegistry = {}\r\nlocal hiddenPropertyRegistry = {}\r\nlocal readonlyRegistry = {}\r\nlocal originalSetmetatable = setmetatable\r\nlocal originalGetmetatable = getmetatable\r\n\r\ngetgenv().syn.setmetatable = function(obj, mt)\r\n    if obj == nil then error(\"bad argument #1 to 'setmetatable' (expected table, got nil)\") end\r\n    if type(obj) ~= \"table\" and type(obj) ~= \"userdata\" then error(\"bad argument #1 to 'setmetatable' (expected table, got \" .. type(obj) .. \")\") end\r\n    local success, result = pcall(originalSetmetatable, obj, mt)\r\n    if success then metatableRegistry[obj] = mt return obj else error(result) end\r\nend\r\n\r\ngetgenv().syn.getmetatable = function(obj)\r\n    if obj == nil then return nil end\r\n    if metatableRegistry[obj] then return metatableRegistry[obj] end\r\n    return originalGetmetatable(obj)\r\nen