n    if type(newFunc) ~= \"function\" then error(\"bad argument #3 to 'safehookmetamethod' (function expected, got \" .. type(newFunc) .. \")\") end\r\n    local mt = metatableRegistry[obj] or originalGetmetatable(obj)\r\n    if not mt then mt = {} metatableRegistry[obj] = mt originalSetmetatable(obj, mt) end\r\n    if not mt[method] then error(\"Cannot hook non-existent metamethod: \" .. tostring(method)) end\r\n    local oldFunc = mt[method]\r\n    mt[method] = function(...) return newFunc(...) end\r\n    metatableRegistry[obj] = mt\r\n    originalSetmetatable(obj, mt)\r\n    return oldFunc\r\nend\r\n\r\nlocal function setReadonlyInternal(tbl, readonly)\r\n    if readonly then\r\n        readonlyRegistry[tbl] = true\r\n        local mt = originalGetmetatable(tbl)\r\n        if not mt then mt = {} originalSetmetatable(tbl, mt) end\r\n        mt.__newindex = function() error(\"attempt to modify a readonly table\", 2) end\r\n        originalSetmetatable(tbl, mt)\r\n    else\r\n        readonlyRegistry[tbl] = nil\r\n        local mt = originalGetmetatable(tbl)\r\n        if mt then mt.__newindex = nil originalSetmetatable(tbl, mt) end\r\n    end\r\nend\r\n\r\ngetgenv().syn.setreadonly = function(tbl, readonly)\r\n    if type(tbl) ~= \"table\" then error(\"bad argument #1 to 'setreadonly' (table expected, got \" .. type(tbl) .. \")\") end\r\n    setReadonlyInternal(tbl, readonly)\r\n    return tbl\r\nend\r\n\r\ngetgenv().syn.isreadonly = function(tbl)\r\n    if type(tbl) ~= \"table\" then return false end\r\n    return readonlyRegistry[tbl] == true\r\nend\r\n\r\ngetgenv().syn.makewriteable = function(tbl)\r\n    if type(tbl) ~= \"table\" then error(\"bad argument #1 to 'makewriteable' (table expected, got \" .. type(tbl) .. \")\") end\r\n    setReadonlyInternal(tbl, false)\r\n    return tbl\r\nend\r\n\r\ngetgenv().syn.makewritable = function(tbl)\r\n    if type(tbl) ~= \"table\" then error(\"bad argument #1 to 'makewritable' (table expected, got \" .. type(tbl) .. \")\