        private void LoadWorker_DoWork(object sender, DoWorkEventArgs e)
        {


            SetStatusText(InitStrings.CheckingWhitelist, 10);
            Thread.Sleep(700);

            SetStatusText(InitStrings.DownloadingData, 30);
            Thread.Sleep(700);

            SetStatusText(InitStrings.CheckingData, 60);
            Thread.Sleep(700);

            var baseDir = AppDomain.CurrentDomain.BaseDirectory;
            var binDir = Path.Combine(baseDir, "bin");

            if (!Directory.Exists(binDir))
                binDir = Path.Combine(Environment.CurrentDirectory, "bin");

            var monacoPath1 = Path.Combine(binDir, "Monaco.html");
            var monacoPath2 = Path.Combine(binDir, "monaco.html");
            bool monacoExists = File.Exists(monacoPath1) || File.Exists(monacoPath2);

            var cefPath1 = Path.Combine(binDir, "CefSharp.dll");
            var cefPath2 = Path.Combine(baseDir, "CefSharp.dll");
            bool cefExists = File.Exists(cefPath1) || File.Exists(cefPath2);

            var themePath = Path.Combine(binDir, "theme-wpf.json");
            bool themeExists = File.Exists(themePath);

            bool allFilesExist = monacoExists && cefExists && themeExists;

            if (allFilesExist)
            {
                SetStatusText(InitStrings.Ready, 100);
                Thread.Sleep(400);
            }
            else
            {
                SetStatusText(InitStrings.DownloadingDlls, 75);
                Thread.Sleep(500);

                SetStatusText(InitStrings.DownloadingMonaco, 85);
                Thread.Sleep(500);

                SetStatusText(InitStrings.DownloadingMonaco, 95);
                Thread.Sleep(500);

                SetStatusText(InitStrings.Ready, 100);
                Thread.Sleep(400);
            }

            WriteAutoexecFiles();

            Dispatcher.Invoke(() =>
            {
                try
                {
                    var Main = new MainWindow();
                    Main.Show();
                    Close();
                }
                catch (Exception ex)
                {
                    MessageBox.Show("UI init exception:\n\n" + ex, "Synapse X",
                        MessageBoxButton.OK, MessageBoxImage.Error);
                    Environment.Exit(0);
                }
            });
        }
    }
